QString valueText(QJsonValue v){if(v.isUndefined())return "—";if(v.isString())return v.toString();if(v.isNull())return "null";if(v.isBool())return v.toBool()?"true":"false";if(v.isDouble())return QString::number(v.toDouble(),'g',12);return QString::fromUtf8(v.isArray()?QJsonDocument(v.toArray()).toJson(QJsonDocument::Compact):QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact));}
QString deltaText(QJsonValue a,QJsonValue b){if(a.isDouble()&&b.isDouble())return QString::number(b.toDouble()-a.toDouble(),'g',12);return a==b?"=":"≠";}
void flattenState(QJsonValue v,QString path,QMap<QString,QJsonValue>& out){if(v.isObject()){auto o=v.toObject();for(auto i=o.begin();i!=o.end();++i)flattenState(i.value(),path+"/"+i.key(),out);}else out[path]=v;}
